/* مولّد هيكلٍ فارغٍ بنفس عقد المحتوى لكل مسار وبُعد — يضمن أنّ العرض لا ينكسر
   قبل ملء طابعٍ ما، ويظهره «قيد الإعداد». */
function _emptyAxis(dimIds) {
  const strengths = {};
  dimIds.forEach(function (d) {
    strengths[d] = { name: null, spectrum: { balance: null, excess: null, deficit: null }, rootsRef: null };
  });
  return {
    identity: { name: null, line: null },
    virtue: null,
    fitra: null,
    qina: { excess: null, deficit: null },
    counterType: false,
    counterNote: "",
    signs: [],
    strengths: strengths,
    _pending: true
  };
}
function _emptyType() {
  return {
    tamasuk:   _emptyAxis(["jasad", "mawarid", "tanzim"]),
    intima:    _emptyAxis(["qiraa", "makana", "ishaam"]),
    hayawiyya: _emptyAxis(["ishtial", "jazibiyya", "tajaddud"])
  };
}

